import{_ as a}from"./chunks/ark_x20_rtk_gps.DQe55Ir8.js";import{_ as r,o as t,c as i,al as n}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"ARK X20 RTK GPS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dronecan/ark_x20_rtk_gps.md","filePath":"zh/dronecan/ark_x20_rtk_gps.md"}'),o={name:"zh/dronecan/ark_x20_rtk_gps.md"};function l(d,e,s,c,h,f){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ark-x20-rtk-gps" tabindex="-1">ARK X20 RTK GPS <a class="header-anchor" href="#ark-x20-rtk-gps" aria-label="Permalink to &quot;ARK X20 RTK GPS&quot;">​</a></h1><p><a href="https://docs.arkelectron.com/gps/ark-x20-rtk-gps" target="_blank" rel="noreferrer">ARK X20 RTK GPS</a> is an open source <a href="./">DroneCAN</a> <a href="./../gps_compass/rtk_gps">RTK GPS</a>, <a href="https://www.u-blox.com/en/product/zed-x20p-module" target="_blank" rel="noreferrer">u-blox ZED-X20P all-band high precision GNSS module</a>, magnetometer, barometer, IMU, buzzer, and safety switch module.</p><p><img src="'+a+'" alt="ARK X20 RTK GPS"></p><h2 id="购买渠道" tabindex="-1">购买渠道 <a class="header-anchor" href="#购买渠道" aria-label="Permalink to &quot;购买渠道&quot;">​</a></h2><p>Order this module from:</p><ul><li><a href="https://arkelectron.com/product/ark-x20-rtk-gps/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="hardware-specifications" tabindex="-1">Hardware Specifications <a class="header-anchor" href="#hardware-specifications" aria-label="Permalink to &quot;Hardware Specifications&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_RTK_GPS" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>传感器 <ul><li>Ublox ZED-X20P <ul><li>All-band all constellation GNSS receiver</li><li>Best position accuracy and availability in different environments</li><li>RTK, PPP-RTK and PPP algorithms expanding the limits of performance</li><li>Highest quality GNSS raw data</li><li>u-blox end-to-end hardened security</li><li>25Hz update rate</li></ul></li><li>ST IIS2MDC Magnetometer</li><li>Bosch BMP390 Barometer</li><li>Invensense ICM-42688-P 6-Axis IMU</li></ul></li><li>STM32F412VGH6 MCU</li><li>Safety Button</li><li>蜂鸣器</li><li>Two Pixhawk Standard CAN Connectors (4 Pin JST GH)</li><li>X20 “UART 2” Connector <ul><li>4 Pin JST GH</li><li>TX, RX, PPS, GND</li></ul></li><li>I2C Expansion Connector <ul><li>4 Pin JST-GH</li><li>5.0V, SCL, SDA, GND</li></ul></li><li>Pixhawk Standard Debug Connector (6 Pin JST SH)</li><li>LED Indicators <ul><li>Safety LED</li><li>GPS Fix</li><li>RTK Status</li><li>RGB system status</li></ul></li><li>USA Built</li><li>Power Requirements <ul><li>5V</li><li>144mA Average</li><li>157mA Max</li></ul></li></ul><h2 id="硬件安装" tabindex="-1">硬件安装 <a class="header-anchor" href="#硬件安装" aria-label="Permalink to &quot;硬件安装&quot;">​</a></h2><h3 id="布线" tabindex="-1">布线 <a class="header-anchor" href="#布线" aria-label="Permalink to &quot;布线&quot;">​</a></h3><p>The ARK X20 RTK GPS is connected to the CAN bus using a Pixhawk standard 4 pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><h3 id="mounting" tabindex="-1">Mounting <a class="header-anchor" href="#mounting" aria-label="Permalink to &quot;Mounting&quot;">​</a></h3><p>The recommended mounting orientation is with the connectors on the board pointing towards the <strong>back of vehicle</strong>.</p><p>The sensor can be mounted anywhere on the frame, but you will need to specify its position, relative to vehicle centre of gravity, during <a href="#px4-configuration">PX4 configuration</a>.</p><h2 id="firmware-setup" tabindex="-1">Firmware Setup <a class="header-anchor" href="#firmware-setup" aria-label="Permalink to &quot;Firmware Setup&quot;">​</a></h2><p>ARK X20 RTK GPS runs the <a href="./px4_cannode_fw">PX4 cannode firmware</a>. As such, it supports firmware update over the CAN bus and <a href="./#node-id-allocation">dynamic node allocation</a>.</p><p>ARK X20 RTK GPS boards ship with recent firmware pre-installed, but if you want to build and flash the latest firmware yourself, refer to the <a href="./px4_cannode_fw#building-the-firmware">cannode firmware build instructions</a>.</p><p>Firmware target: <code>ark_can-rtk-gps_default</code> Bootloader target: <code>ark_can-rtk-gps_canbootloader</code></p><h2 id="flight-controller-setup" tabindex="-1">Flight Controller Setup <a class="header-anchor" href="#flight-controller-setup" aria-label="Permalink to &quot;Flight Controller Setup&quot;">​</a></h2><h3 id="enabling-dronecan" tabindex="-1">Enabling DroneCAN <a class="header-anchor" href="#enabling-dronecan" aria-label="Permalink to &quot;Enabling DroneCAN&quot;">​</a></h3><p>In order to use the ARK X20 RTK GPS, connect it to the Pixhawk CAN bus and enable the DroneCAN driver by setting parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs">DroneCAN ESCs</a>).</p><p>步骤如下：</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> or <code>3</code> and reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect ARK X20 RTK GPS CAN to the Pixhawk CAN.</li></ul><p>Once enabled, the module will be detected on boot. GPS data should arrive at 10Hz.</p><h3 id="px4-配置" tabindex="-1">PX4 配置 <a class="header-anchor" href="#px4-配置" aria-label="Permalink to &quot;PX4 配置&quot;">​</a></h3><p>You need to set necessary <a href="./">DroneCAN</a> parameters and define offsets if the sensor is not centred within the vehicle:</p><ul><li>Enable GPS yaw fusion by setting bit 3 of <a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a> to true.</li><li>Enable GPS blending to ensure the heading is always published by setting <a href="./../advanced_config/parameter_reference#SENS_GPS_MASK">SENS_GPS_MASK</a> to 7 (all three bits checked).</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_GPS">UAVCAN_SUB_GPS</a>, <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_MAG">UAVCAN_SUB_MAG</a>, and <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_BARO">UAVCAN_SUB_BARO</a>.</li><li>The parameters <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFX">SENS_GPS0_OFFX</a>, <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFY">SENS_GPS0_OFFY</a> and <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFZ">SENS_GPS0_OFFZ</a> can be set to account for the offset of the ARK X20 RTK GPS from the vehicles centre of gravity.</li></ul><h3 id="ark-x20-rtk-gps-configuration" tabindex="-1">ARK X20 RTK GPS Configuration <a class="header-anchor" href="#ark-x20-rtk-gps-configuration" aria-label="Permalink to &quot;ARK X20 RTK GPS Configuration&quot;">​</a></h3><p>You may need to <a href="./../dronecan/#qgc-cannode-parameter-configuration">configure the following parameters</a> on the ARK X20 RTK GPS itself:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><a id="CANNODE_NODE_ID"></a><a href="./../advanced_config/parameter_reference#CANNODE_NODE_ID">CANNODE_NODE_ID</a></td><td>CAN node ID (0 for dynamic allocation). If set to 0 (default), dynamic node allocation is used. Set to 1-125 to use a static node ID.</td></tr><tr><td><a id="CANNODE_TERM"></a><a href="./../advanced_config/parameter_reference#CANNODE_TERM">CANNODE_TERM</a></td><td>CAN built-in bus termination. Set to <code>1</code> if this is the last node on the CAN bus.</td></tr><tr><td><a id="GPS_UBX_BAUD1"></a><a href="./../advanced_config/parameter_reference#GPS_UBX_BAUD1">GPS_UBX_BAUD1</a></td><td>UART1 baudrate after the link is auto-detected. Board default is <code>921600</code>.</td></tr><tr><td><a id="GPS_UBX_BAUD2"></a><a href="./../advanced_config/parameter_reference#GPS_UBX_BAUD2">GPS_UBX_BAUD2</a></td><td>UART2 baudrate (default <code>230400</code>).</td></tr></tbody></table><h3 id="setting-up-rover-and-fixed-base" tabindex="-1">Setting Up Rover and Fixed Base <a class="header-anchor" href="#setting-up-rover-and-fixed-base" aria-label="Permalink to &quot;Setting Up Rover and Fixed Base&quot;">​</a></h3><p>Position of the rover is established using RTCM messages from the RTK base module (the base module is connected to QGC, which sends the RTCM information to PX4 via MAVLink).</p><p>PX4 DroneCAN parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#UAVCAN_PUB_RTCM">UAVCAN_PUB_RTCM</a>: <ul><li>Makes PX4 publish RTCM messages (<a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#rtcmstream" target="_blank" rel="noreferrer">RTCMStream</a>) to the bus (which it gets from the RTK base module via QGC).</li></ul></li></ul><p>Rover module parameters (also <a href="./../dronecan/#qgc-cannode-parameter-configuration">set using QGC</a>):</p><ul><li><a href="./../advanced_config/parameter_reference#CANNODE_SUB_RTCM">CANNODE_SUB_RTCM</a> tells the rover that it should subscribe to <a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#rtcmstream" target="_blank" rel="noreferrer">RTCMStream</a> RTCM messages on the bus (from the moving base).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Use <a href="./../advanced_config/parameter_reference#UAVCAN_PUB_MBD">UAVCAN_PUB_MBD</a> and <a href="./../advanced_config/parameter_reference#CANNODE_SUB_MBD">CANNODE_SUB_MBD</a> instead if you want to implement moving base (see below) at the same time.</p></div><p>For more information see <a href="./../dronecan/#rover-and-fixed-base">Rover and Fixed Base</a> in the DroneCAN guide.</p><h2 id="led含义" tabindex="-1">LED含义 <a class="header-anchor" href="#led含义" aria-label="Permalink to &quot;LED含义&quot;">​</a></h2><ul><li><p>The GPS status lights are located to the right of the connectors</p><ul><li>Blinking green is GPS fix</li><li>Blinking blue is received corrections and RTK Float</li><li>Solid blue is RTK Fixed</li></ul></li><li><p>The CAN status lights are located top the left of the connectors</p><ul><li>Slow blinking green is waiting for CAN connection</li><li>Fast blinking green is normal operation</li><li>Slow blinking green and blue is CAN enumeration</li><li>Fast blinking blue and red is firmware update in progress</li><li>Blinking red is error <ul><li>If you see a red LED there is an error and you should check the following <ul><li>Make sure the flight controller has an SD card installed</li><li>Make sure the ARK X20 RTK GPS has <code>ark_can-rtk-gps_canbootloader</code> installed prior to flashing <code>ark_can-rtk-gps_default</code></li><li>Remove binaries from the root and ufw directories of the SD card and try to build and flash again</li></ul></li></ul></li></ul></li></ul><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/gps/ark-x20-rtk-gps" target="_blank" rel="noreferrer">ARK X20 RTK GPS Documentation</a> (ARK Docs)</li></ul>',42)])])}const m=r(o,[["render",l]]);export{p as __pageData,m as default};
